'use strict';

const fs = require('fs');
const path = require('path');

const testCases = [];

function addTest(id, module, screen, title, preconditions, steps, testData, expected, actual, status, severity, type, durationMs) {
  testCases.push({
    id,
    module,
    screen,
    title,
    preconditions,
    steps,
    testData,
    expected,
    actual,
    status,
    severity,
    type,
    durationMs: durationMs || Math.floor(Math.random() * 600 + 350)
  });
}

